+package com.toolshare.loan;
+
+import java.time.LocalDate;
+import lombok.RequiredArgsConstructor;
+import org.springframework.stereotype.Service;
+import org.springframework.transaction.annotation.Transactional;
+
+@Service
+@RequiredArgsConstructor
+public class LoanService {
+    private final ToolRepository tools;
+    private final LoanRepository loans;
+
+    @Transactional
+    public Loan requestLoan(Long toolId, Long memberId, LocalDate startDate, LocalDate endDate) {
+        Tool tool = tools.findById(toolId).orElseThrow();
+        if (startDate.isAfter(endDate)) throw new InvalidLoanPeriodException();
+        return loans.save(new Loan(tool.getId(), memberId, startDate, endDate));
+    }
+}

