@@ -0,0 +1,20 @@
+package com.toolshare.loan;
+
+import java.time.LocalDate;
+import lombok.RequiredArgsConstructor;
+import org.springframework.web.bind.annotation.*;
+
+@RestController
+@RequiredArgsConstructor
+public class LoanController {
+    private final LoanService service;
+
+    @PostMapping("/api/tools/{toolId}/loans")
+    public CreatedResponse create(@PathVariable Long toolId, @RequestBody LoanRequest request) {
+        Loan saved = service.requestLoan(toolId, request.memberId(), request.startDate(), request.endDate());
+        return new CreatedResponse(saved.getId());
+    }
+
+    public record LoanRequest(Long memberId, LocalDate startDate, LocalDate endDate) {}
+    public record CreatedResponse(Long loanId) {}
+}

diff --git a/frontend/src/features/loan/LoanRequestPanel.tsx b/frontend/src/features/loan/LoanRequestPanel.tsx
--- a/frontend/src/features/loan/LoanRequestPanel.tsx
+++ b/frontend/src/features/loan/LoanRequestPanel.tsx
@@ -1,2 +1,26 @@
-export function FeaturePanel() { return null; }
-// 화면 구현 예정
+import { useState } from 'react';
+import { api } from '../../lib/api';
+
+type Props = { toolId: number; memberId: number; reload: () => Promise<void> };
+
+export function LoanRequestPanel({ toolId, memberId, reload }: Props) {
+  const [startDate, setStartDate] = useState('2026-11-16');
+  const [endDate, setEndDate] = useState('2026-11-18');
+  const [error, setError] = useState('');
+  async function submit() {
+    setError('');
+    try {
+      await api.post(`/api/tools/${toolId}/loans`, { memberId, startDate, endDate });
+      await reload();
+    } catch {
+      setError('요청을 처리하지 못했습니다. 잠시 후 다시 시도해주세요.');
+    }
+  }
+  return <section>
+    <h2>대여 요청</h2>
+    <label>시작일<input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} /></label>
+    <label>반납일<input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} /></label>
+    {error && <p role="alert">{error}</p>}
+    <button onClick={submit}>저장하기</button>
+  </section>;
+}

