+    @Test
+    void returnsCreatedRecordForValidRequest() {
+        var tools = mock(ToolRepository.class);
+        var loans = mock(LoanRepository.class);
+        var resource = mock(Tool.class);
+        when(tools.findById(1L)).thenReturn(Optional.of(resource));
+        when(resource.getId()).thenReturn(1L);
+        when(loans.save(any(Loan.class))).thenAnswer(invocation -> invocation.getArgument(0));
